-- Traductions en anglais (en) et en arabe (ar) des dialogues des thèmes « Dans la cuisine » et « Cuisiner » (non relues, reviewed = 0).
-- À lancer APRÈS frenchdb_9_themes_cuisine.sql. Se relance sans danger (INSERT IGNORE) :
--   docker exec -i french-db sh -c 'mysql -u root -p"$MYSQL_ROOT_PASSWORD" "$MYSQL_DATABASE"' < init-db/frenchdb_9_traductions_en_ar_themes_cuisine.sql
SET NAMES utf8mb4;

INSERT IGNORE INTO `translations` (`kind`, `entity_id`, `lang`, `content`, `reviewed`)
SELECT 'THEME_DIALOGUE', t.`id`, 'en', 'Chef: Hello, Léa. Today is your first day in the kitchen.\n\nLéa: Hello, chef. I''m ready!\n\nChef: Very good. First, put on your apron and wash your hands.\n\nLéa: Yes, chef. Where are the knives?\n\nChef: In the drawer, on the left. Take the chopping board too.\n\nLéa: For the carrots, shall I take the peeler?\n\nChef: Yes, it''s next to the sink. Then you slice the carrots into rounds.\n\nLéa: OK. And where is the big saucepan?\n\nChef: On the shelf, up there. The frying pan is down below, under the worktop.\n\nLéa: And the whisk? And the colander?\n\nChef: In the cupboard, in front of you. Careful, the oven is very hot: always use the oven mitts!\n\nLéa: Understood, chef. I''ll start by peeling the carrots.\n\nChef: Perfect. And don''t forget: afterwards, you clean everything!', 0 FROM `themes` t WHERE t.`nom` = 'Dans la cuisine';
INSERT IGNORE INTO `translations` (`kind`, `entity_id`, `lang`, `content`, `reviewed`)
SELECT 'THEME_DIALOGUE', t.`id`, 'ar', 'الشيف: صباح الخير يا ليا. اليوم هو أول يوم لكِ في المطبخ.\n\nليا: صباح الخير يا شيف. أنا جاهزة!\n\nالشيف: حسنًا. أولًا، ارتدي المئزر واغسلي يديكِ.\n\nليا: نعم يا شيف. أين السكاكين؟\n\nالشيف: في الدرج على اليسار. خذي أيضًا لوح التقطيع.\n\nليا: بالنسبة للجزر، هل آخذ المقشرة؟\n\nالشيف: نعم، هي بجانب الحوض. بعد ذلك تقطّعين الجزر إلى شرائح دائرية.\n\nليا: حسنًا. وأين القدر الكبير؟\n\nالشيف: على الرف في الأعلى. والمقلاة في الأسفل، تحت سطح العمل.\n\nليا: وماذا عن المخفقة؟ والمصفاة؟\n\nالشيف: في الخزانة أمامكِ. انتبهي، الفرن ساخن جدًا: استعملي دائمًا قفازات الفرن!\n\nليا: فهمت يا شيف. سأبدأ بتقشير الجزر.\n\nالشيف: ممتاز. ولا تنسي: بعد ذلك تنظّفين كل شيء!', 0 FROM `themes` t WHERE t.`nom` = 'Dans la cuisine';
INSERT IGNORE INTO `translations` (`kind`, `entity_id`, `lang`, `content`, `reviewed`)
SELECT 'THEME_DIALOGUE', t.`id`, 'en', 'Chef: Léa, table twelve: one roast chicken and one vegetable soup.\n\nLéa: Yes, chef! Shall I start with the soup?\n\nChef: Yes. Peel the potatoes and chop the onions.\n\nLéa: Shall I sauté them in the saucepan with a little oil?\n\nChef: Yes. Then add the water and boil for twenty minutes.\n\nLéa: Shall I stir from time to time?\n\nChef: Exactly. Then you taste it, and add salt and pepper.\n\nLéa: And the chicken? Do I put it in the oven?\n\nChef: Yes, at two hundred degrees, for forty minutes. Keep an eye on the cooking!\n\nLéa: Chef, the chicken is cooked. Shall I take it out?\n\nChef: Wait: let it rest for five minutes, then cut it into slices.\n\nLéa: And for plating up?\n\nChef: A little mash, two slices of chicken, and the sauce around it.\n\nLéa: Here you are, chef. It''s ready!\n\nChef: Well done! Table twelve, service!', 0 FROM `themes` t WHERE t.`nom` = 'Cuisiner';
INSERT IGNORE INTO `translations` (`kind`, `entity_id`, `lang`, `content`, `reviewed`)
SELECT 'THEME_DIALOGUE', t.`id`, 'ar', 'الشيف: ليا، الطاولة اثنا عشر: دجاجة مشوية وحساء خضار.\n\nليا: نعم يا شيف! هل أبدأ بالحساء؟\n\nالشيف: نعم. قشّري البطاطس وقطّعي البصل.\n\nليا: هل أحمّرها في القدر مع قليل من الزيت؟\n\nالشيف: نعم. بعد ذلك أضيفي الماء واتركيه يغلي لمدة عشرين دقيقة.\n\nليا: هل أحرّك من حين لآخر؟\n\nالشيف: بالضبط. ثم تتذوقين وتضيفين الملح والفلفل.\n\nليا: وماذا عن الدجاج؟ هل أضعه في الفرن؟\n\nالشيف: نعم، على مئتي درجة لمدة أربعين دقيقة. راقبي الطهي!\n\nليا: يا شيف، الدجاج أصبح مطبوخًا. هل أخرجه؟\n\nالشيف: انتظري: اتركيه يرتاح خمس دقائق ثم قطّعيه إلى شرائح.\n\nليا: وماذا عن تقديم الطبق؟\n\nالشيف: قليل من الهريس وشريحتان من الدجاج والصلصة حولهما.\n\nليا: تفضّل يا شيف. كل شيء جاهز!\n\nالشيف: أحسنتِ! الطاولة اثنا عشر، انطلقوا!', 0 FROM `themes` t WHERE t.`nom` = 'Cuisiner';
